public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String dummyLine = scanner.nextLine();
        String inputLine = scanner.nextLine();

        int maxLength = 0;
        int totalTokens = 0;
        int position = 0;
        int lastPosition = 0;

        while (position < inputLine.lastIndexOf(')')) {
            int startIdx = inputLine.indexOf('(', position);
            int endIdx = inputLine.indexOf(')', startIdx);
            String segment = inputLine.substring(lastPosition, startIdx);
            StringTokenizer tokenizer = new StringTokenizer(segment, "_");
            while (tokenizer.hasMoreTokens()) {
                int length = tokenizer.nextToken().length();
                if (length > maxLength) maxLength = length;
            }
            String insideContent = inputLine.substring(startIdx + 1, endIdx);
            StringTokenizer innerTokenizer = new StringTokenizer(insideContent, "_");
            while (innerTokenizer.hasMoreTokens()) {
                String token = innerTokenizer.nextToken();
                if (!token.isEmpty()) totalTokens++;
            }
            lastPosition = endIdx + 1;
            position = endIdx;
        }

        String remainingPart = inputLine.substring(lastPosition);
        StringTokenizer remainingTokenizer = new StringTokenizer(remainingPart, "_");
        while (remainingTokenizer.hasMoreTokens()) {
            int length = remainingTokenizer.nextToken().length();
            if (length > maxLength) maxLength = length;
        }

