#include <iostream>
#include <string>
#include <sstream>

int main() {
    std::string dummyLine, inputLine;
    std::getline(std::cin, dummyLine);
    std::getline(std::cin, inputLine);

    int maxLength = 0;
    int totalTokens = 0;
    size_t position = 0;
    size_t lastPosition = 0;

    while (true) {
        size_t startIdx = inputLine.find('(', position);
        if (startIdx == std::string::npos || startIdx > inputLine.rfind(')')) {
            break;
        }
        size_t endIdx = inputLine.find(')', startIdx);
        if (endIdx == std::string::npos) {
            break;
        }

        std::string segment = inputLine.substr(lastPosition, startIdx - lastPosition);
        std::istringstream segmentStream(segment);
        std::string token;
        while (std::getline(segmentStream, token, '_')) {
            if (!token.empty()) {
                int length = token.length();
                if (length > maxLength) maxLength = length;
            }
        }

        std::string insideContent = inputLine.substr(startIdx + 1, endIdx - startIdx - 1);
        std::istringstream insideStream(insideContent);
        while (insideStream >> token) {
            if (!token.empty()) {
                totalTokens++;
            }
        }

        lastPosition = endIdx + 1;
        position = endIdx + 1;
    }

    // Process remaining part after last parenthesis
    std::string remainingPart = inputLine.substr(lastPosition);
    std::istringstream remainingStream(remainingPart);
    while (remainingStream >> token) {
        int length = token.length();
        if (length > maxLength) maxLength = length;
    }

    std::cout << maxLength << " " << totalTokens << std::endl;

    return 0;
}
